// Simple endless runner based on IDEA.md
// Canvas with id="game"

const canvas = document.getElementById('game');
if (!canvas) {
  throw new Error('Canvas element with id "game" not found');
}
const ctx = canvas.getContext('2d');
const WIDTH = canvas.width;
const HEIGHT = canvas.height;

// Player configuration
const player = {
  x: 50,
  size: 20,
  // ground position (bottom of canvas minus player size)
  groundY: HEIGHT - 20,
  y: HEIGHT - 20,
  vy: 0,
  gravity: 0.6,
  jumpStrength: -12,
  isJumping: false,
};

// Obstacle configuration
const obstacles = [];
const obstacleSpeed = 4;
let obstacleTimer = 0;
const obstacleInterval = 1500; // ms

let score = 0;
let lastTimestamp = 0;
let gameOver = false;

function spawnObstacle() {
  const size = 20 + Math.random() * 30; // random width/height
  obstacles.push({
    x: WIDTH,
    y: HEIGHT - size,
    width: size,
    height: size,
  });
}

function resetGame() {
  player.y = player.groundY;
  player.vy = 0;
  player.isJumping = false;
  obstacles.length = 0;
  obstacleTimer = 0;
  score = 0;
  gameOver = false;
  lastTimestamp = performance.now();
  requestAnimationFrame(loop);
}

function handleJump() {
  if (!player.isJumping) {
    player.vy = player.jumpStrength;
    player.isJumping = true;
  }
}

// Input: spacebar or mouse click/tap
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') handleJump();
});
canvas.addEventListener('mousedown', handleJump);
canvas.addEventListener('touchstart', (e) => {
  e.preventDefault();
  handleJump();
});

function update(delta) {
  // Player physics
  player.vy += player.gravity;
  player.y += player.vy;
  if (player.y >= player.groundY) {
    player.y = player.groundY;
    player.vy = 0;
    player.isJumping = false;
  }

  // Obstacles movement
  for (let i = obstacles.length - 1; i >= 0; i--) {
    const obs = obstacles[i];
    obs.x -= obstacleSpeed;
    // Remove off‑screen obstacles
    if (obs.x + obs.width < 0) obstacles.splice(i, 1);
  }

  // Spawn new obstacles
  obstacleTimer += delta;
  if (obstacleTimer > obstacleInterval) {
    spawnObstacle();
    obstacleTimer = 0;
  }

  // Collision detection (AABB)
  for (const obs of obstacles) {
    if (
      player.x < obs.x + obs.width &&
      player.x + player.size > obs.x &&
      player.y < obs.y + obs.height &&
      player.y + player.size > obs.y
    ) {
      gameOver = true;
      break;
    }
  }

  // Score increases with time
  score += delta / 1000;
}

function draw() {
  ctx.clearRect(0, 0, WIDTH, HEIGHT);

  // Draw player (black square)
  ctx.fillStyle = '#000';
  ctx.fillRect(player.x, player.y, player.size, player.size);

  // Draw obstacles (gray rectangles)
  ctx.fillStyle = '#555';
  for (const obs of obstacles) {
    ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
  }

  // Draw score
  ctx.fillStyle = '#000';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 20);

  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    ctx.fillStyle = '#fff';
    ctx.font = '24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2 - 10);
    ctx.fillText('Final Score: ' + Math.floor(score), WIDTH / 2, HEIGHT / 2 + 20);
    ctx.textAlign = 'start';
  }
}

function loop(timestamp) {
  const delta = timestamp - lastTimestamp;
  lastTimestamp = timestamp;
  if (!gameOver) {
    update(delta);
    draw();
    requestAnimationFrame(loop);
  } else {
    draw(); // draw final frame with overlay
  }
}

// Start the game
resetGame();
